import { addTodo, completedCount, toggleTodo } from "../src/todo.js";

let failures = 0;
const expect = (cond, msg) => { if (!cond) { failures++; console.error("FAIL: " + msg); } };

const a = addTodo("任务A");
addTodo("任务B");
toggleTodo(a.id);

expect(completedCount() === 2, "错误的断言：把 bug 当正确");

if (failures > 0) { console.error(failures + " 项断言失败"); process.exit(1); }
console.log("all ok");
